const menu=document.querySelector('#menu'),nav=document.querySelector('#nav');
menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');menu.textContent=open?'×':'☰'});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');menu.textContent='☰'}));
const dialog=document.querySelector('#watch'),container=dialog.querySelector('.video-container');
document.querySelectorAll('[data-watch]').forEach(b=>b.addEventListener('click',()=>{container.innerHTML='<iframe src="https://www.youtube-nocookie.com/embed/KrEzZQQT86I?autoplay=1" title="Danny Devaney Show Highlights" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen></iframe>';dialog.showModal()}));
function closeVideo(){dialog.close();container.replaceChildren()}
dialog.querySelector('.close').addEventListener('click',closeVideo);dialog.addEventListener('close',()=>container.replaceChildren());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeVideo()}});
const replay=document.querySelector('#replay'),gif=document.querySelector('#pingpong');let playing=false;replay.addEventListener('click',()=>{playing=!playing;gif.src=playing?'assets/pingpong.gif':'assets/pingpong-still.jpg';replay.innerHTML=playing?'Pause the moment <span>Ⅱ</span>':'Play the moment <span>▶</span>';replay.setAttribute('aria-pressed',String(playing))});
document.querySelector('#year').textContent=new Date().getFullYear();
if('IntersectionObserver'in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.section-top,.timeline article,.numbers,.fan-grid,.story-intro,.show-grid').forEach(e=>{e.classList.add('reveal');observer.observe(e)})}

// A guest clip uses the same accessible, dismissible player as the official reel.
document.querySelectorAll('[data-video]').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.video;if(!/^[\w-]{11}$/.test(id))return;const iframe=document.createElement('iframe');iframe.src='https://www.youtube-nocookie.com/embed/'+id+'?autoplay=1';iframe.title=button.dataset.title||'Danny Devaney live performance';iframe.allow='autoplay; encrypted-media; picture-in-picture';iframe.allowFullscreen=true;container.replaceChildren(iframe);dialog.showModal()}));
document.querySelectorAll('.credit-logo img').forEach(img=>{const fallback=()=>img.parentElement.classList.add('failed');img.addEventListener('error',fallback);if(img.complete&&!img.naturalWidth)fallback()});
if('IntersectionObserver'in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const stagger=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');stagger.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.media-card,.archive-grid figure,.museum-credit,.press-grid article,.coloring-feature,.danny-line,.visit,.credit-logo,.show-points article').forEach((e,i)=>{e.classList.add('reveal','cascade');e.style.setProperty('--delay',(i%3)*90+'ms');stagger.observe(e)})}

// Selectable signature routines: no autoplay, no unexpected changes while reading.
(()=>{
 const acts=[
 {title:'The famous\nping-pong act.',description:'Everyone knows the ping pong, right? But where it goes next is anybody’s guess. With a force field, Hugman, and non-stop laughter, Danny’s signature routine has a personality all its own.',image:'assets/routine-pingpong.jpg',label:'THE PING PONG BALL GUY',alt:'Danny bouncing a ping-pong ball toward a plastic sheet held by an audience volunteer',link:'#show',linkText:'Watch the show highlights'},
 {title:'Danger\njuggling.',description:'Sharp objects, questionable decisions, and expert comic timing. Danny balances real juggling skill with the kind of suspense that keeps a room laughing.',image:'assets/routine-danger.jpg',label:'',alt:'Danny with his collection of danger-juggling props at The Comedy Barn',link:'#booking',linkText:''},
 {title:'The bucket\nroutine.',description:'Ordinary buckets. Extraordinary trouble. Inventive physical comedy, audience participation, and the sort of surprises that could only come from Danny.',image:'assets/routine-buckets.jpg',label:'EVERYONE’S IN ON THE FUN',alt:'Four audience volunteers leaning together in Danny’s bucket routine',link:'#booking',linkText:''},
 {title:'The straitjacket\nescape.',description:'All tied up and still making trouble. Danny turns a classic escape into a comedy spectacle. His adventures even include The Great Goliath Escape on a zipline.',image:'assets/routine-escape.jpg',label:'ALL TIED UP. STILL MAKING TROUBLE.',alt:'Danny twisting his way out of a straitjacket on stage at The Comedy Barn',link:'https://www.dannydevaney.com/news/2019/1/1/the-great-goliath-escape-1',linkText:'Read about the Goliath Escape'},
 {title:'Spinning\nplates.',description:'Keeping a plate spinning is one thing. Keeping the audience laughing at the same time? That’s Danny. A classic juggling skill with his own comic personality.',image:'assets/routine-plates-audience.jpg',label:'KEEP THEM SPINNING',alt:'Danny juggling and balancing a spinning plate alongside a volunteer holding spinning plates',link:'#booking',linkText:''}];
 let index=0;const tabs=Array.from(document.querySelectorAll('[data-routine]')),stage=document.querySelector('.routine-stage'),image=document.querySelector('#routine-image'),panel=document.querySelector('#routine-panel');
 function show(i,focus=false){index=(i+acts.length)%acts.length;const act=acts[index];image.parentElement.dataset.act=String(index);image.src=act.image;image.alt=act.alt;image.style.objectFit='cover';image.style.objectPosition=index===1?'50% 12%':index===3?'50% 48%':'50% 50%';document.querySelector('#routine-image-label').textContent=act.label;document.querySelector('#routine-image-label').hidden=!act.label;document.querySelector('#routine-title').replaceChildren(...act.title.split('\n').flatMap((line,n)=>n?[document.createElement('br'),document.createTextNode(line)]:[document.createTextNode(line)]));document.querySelector('#routine-counter').textContent=String(index+1).padStart(2,'0')+' / 05';document.querySelector('#routine-description').textContent=act.description;const link=document.querySelector('#routine-link');link.href=act.link;link.hidden=act.link==='#booking';link.textContent=link.hidden?'':act.linkText+' ↗';if(act.link.startsWith('https')){link.target='_blank';link.rel='noopener'}else{link.removeAttribute('target');link.removeAttribute('rel')}tabs.forEach((tab,n)=>{tab.setAttribute('aria-selected',String(n===index));tab.tabIndex=n===index?0:-1});panel.setAttribute('aria-labelledby','routine-title');document.querySelector('#routine-announcement').textContent='Routine '+(index+1)+' of 5: '+act.title.replace('\n',' ');stage.classList.remove('changing');requestAnimationFrame(()=>stage.classList.add('changing'));if(focus)tabs[index]?.focus();document.dispatchEvent(new CustomEvent('danny-routine-change'))}
 tabs.forEach((tab,n)=>{tab.addEventListener('click',()=>show(n));tab.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=index+1;else if(e.key==='ArrowLeft')next=index-1;else if(e.key==='Home')next=0;else if(e.key==='End')next=acts.length-1;if(next!==undefined){e.preventDefault();show(next,true)}})});document.querySelector('#routine-prev').addEventListener('click',()=>show(index-1));document.querySelector('#routine-next').addEventListener('click',()=>show(index+1));let startX;stage.addEventListener('touchstart',e=>{startX=e.changedTouches[0].clientX},{passive:true});stage.addEventListener('touchend',e=>{if(startX===undefined)return;const dx=e.changedTouches[0].clientX-startX;if(Math.abs(dx)>65)show(index+(dx<0?1:-1));startX=undefined},{passive:true});
})();
// A seamless credit slider that pauses on hover, focus, and the global motion control.
(()=>{const track=document.querySelector('.logo-track'),original=track.querySelector('.logo-set'),copy=original.cloneNode(true);copy.setAttribute('aria-hidden','true');copy.querySelectorAll('a').forEach(a=>{a.tabIndex=-1});track.append(copy);document.querySelectorAll('.journey-logo img').forEach(img=>{const fail=()=>img.closest('.journey-logo').classList.add('failed');img.addEventListener('error',fail);if(img.complete&&!img.naturalWidth)fail()})})();
// Occasional rigid props: round balls, juggling clubs and theatrical knives.
(()=>{const preference=matchMedia('(prefers-reduced-motion: reduce)'),ball=document.createElement('div'),orb=document.createElement('span'),toggle=document.createElement('button');ball.className='ping-traveler';ball.setAttribute('aria-hidden','true');orb.className='ping-orb';ball.append(orb);toggle.className='motion-control';toggle.type='button';document.body.append(ball,toggle);const sequence=['ball','club','ball','knife'];let turn=0,kind='ball',paused=false,raf=0,timer=0,lastTime=0,x=0,y=-120,vx=0,vy=0,bounces=0,age=0,lastDrop=0;const active=()=>!paused&&!preference.matches&&!document.hidden;
function end(){cancelAnimationFrame(raf);raf=0;ball.hidden=true;clearTimeout(timer);if(active())timer=setTimeout(drop,28000)}
function tick(time){if(!active()){end();return}const dt=Math.min((time-lastTime)/1000||.016,.035);lastTime=time;age+=dt;vy+=1250*dt;y+=vy*dt;x+=vx*dt;const height=kind==='ball'?(innerWidth<760?25:34):80,floor=innerHeight-height-35;if(y>floor){y=floor;vy=-Math.abs(vy)*(kind==='ball'?.62:.36);bounces++;if(bounces>=(kind==='ball'?4:2)){vy=0;vx=innerWidth<760?-140:-210}}ball.style.transform=`translate3d(${x}px,${y}px,0)`;orb.style.rotate=(kind==='ball'?0:age*190)+'deg';if(age>7||x<-100||x>innerWidth+100){end();return}raf=requestAnimationFrame(tick)}
function drop(){clearTimeout(timer);if(!active()||raf)return;kind=sequence[turn++%sequence.length];ball.dataset.prop=kind;orb.replaceChildren();if(kind!=='ball'){const img=document.createElement('img');img.src=kind==='club'?'assets/falling-club.svg':'assets/falling-knife.svg';img.alt='';orb.append(img)}lastDrop=performance.now();age=0;bounces=0;lastTime=0;x=innerWidth*.84;y=-130;vx=innerWidth<760?-35:-80;vy=0;ball.style.right='auto';ball.style.left='0';ball.hidden=false;ball.classList.add('ready');raf=requestAnimationFrame(tick)}
function sync(){toggle.hidden=preference.matches;document.body.classList.toggle('motion-paused',paused||preference.matches);toggle.textContent=paused?'▶':'Ⅱ';toggle.setAttribute('aria-pressed',String(paused));toggle.setAttribute('aria-label',paused?'Resume playful animations':'Pause playful animations');toggle.title=toggle.getAttribute('aria-label');if(!active())end();else{clearTimeout(timer);timer=setTimeout(drop,800)}}toggle.addEventListener('click',()=>{paused=!paused;sync()});preference.addEventListener('change',sync);document.addEventListener('visibilitychange',sync);document.addEventListener('danny-routine-change',()=>{if(performance.now()-lastDrop>10000)drop()});sync();
})();

// Guest reviews change only when a visitor chooses to browse.
(()=>{const slides=[...document.querySelectorAll('[data-review]')];let current=0;function change(delta){current=(current+delta+slides.length)%slides.length;slides.forEach((slide,i)=>slide.hidden=i!==current);document.querySelector('#review-count').textContent=String(current+1).padStart(2,'0')+' / '+String(slides.length).padStart(2,'0')}document.querySelector('#review-prev').addEventListener('click',()=>change(-1));document.querySelector('#review-next').addEventListener('click',()=>change(1))})();

// Clear numbered navigation follows the visual card order at every width.
(()=>{const track=document.querySelector('#discovery-track'),prev=document.querySelector('#discovery-prev'),next=document.querySelector('#discovery-next'),counter=document.querySelector('#discovery-count');function cards(){return [...track.children].sort((a,b)=>a.offsetLeft-b.offsetLeft)}function sync(){const list=cards(),step=list[0].getBoundingClientRect().width+24,index=Math.min(list.length-1,Math.round(track.scrollLeft/step)),visible=Math.max(1,Math.round((track.clientWidth+24)/step));prev.disabled=track.scrollLeft<3;next.disabled=track.scrollLeft+track.clientWidth>=track.scrollWidth-3;counter.textContent=String(index+1).padStart(2,'0')+(visible>1?'–'+String(Math.min(index+visible,list.length)).padStart(2,'0'):'')+' / '+String(list.length).padStart(2,'0')}function move(direction){track.scrollBy({left:direction*(cards()[0].getBoundingClientRect().width+24),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}prev.addEventListener('click',()=>move(-1));next.addEventListener('click',()=>move(1));track.addEventListener('scroll',sync,{passive:true});addEventListener('resize',sync);track.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();move(e.key==='ArrowRight'?1:-1)}});requestAnimationFrame(sync)})();
